#!/usr/bin/env bash
set -euo pipefail
metadata_manifest() { local dir="$1"; jq -n --arg server "$SERVER_ID" --arg time "$(date -u '+%Y-%m-%dT%H:%M:%SZ')" --arg version "$(cat "${VBACKUP_ROOT:-.}/VERSION" 2>/dev/null || echo unknown)" --slurpfile docker "$dir/metadata/docker.json" --slurpfile systemd "$dir/metadata/systemd.json" --slurpfile database "$dir/metadata/database.json" --slurpfile webserver "$dir/metadata/webserver.json" --rawfile os /etc/os-release --arg kernel "$(uname -r)" --slurpfile network "$dir/metadata/network.json" '{server:$server,os:$os,kernel:$kernel,docker:$docker[0],systemd:$systemd[0],database:$database[0],webserver:$webserver[0],network:$network[0],backup_time:$time,version:$version,restore_order:["network","system","database","docker","systemd","website","ssl","verify","telegram"]}' >"$dir/manifest.json"; }
